SELECT * FROM customer_account


    AND (LOCATE(#{filter.keyword},username) > 0 OR LOCATE(#{filter.keyword},display_name) > 0)

  AND status = #{filter.status}
  AND valid_until >= #{filter.validUntilFrom}
  AND valid_until < #{filter.validUntilTo}

    AND valid_from > #{filter.now}
    AND valid_from <= #{filter.now} AND valid_until > #{filter.now}
    AND valid_until <= #{filter.now}


ORDER BY

  valid_until ASC, id ASC
  valid_until DESC, id DESC
  (last_login_at IS NULL) ASC, last_login_at ASC, id ASC
  (last_login_at IS NULL) ASC, last_login_at DESC, id DESC
  created_at ASC, id ASC
  created_at DESC, id DESC

